import{_ as t,o as r,c as i,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"General Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/general.md","filePath":"user-guide/settings/general.md","lastUpdated":1788247711000}'),o={name:"user-guide/settings/general.md"};function n(s,e,l,d,c,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h1><p>General Settings covers core application behaviors, search window dimensions and visual layouts, result type priority weights, and preview provider sequences. The page is divided into six top tabs: <strong>System</strong>, <strong>Quick Search Window</strong>, <strong>Full Search Window</strong>, <strong>Preview Window</strong>, <strong>Quick Navigation</strong>, and <strong>Previews &amp; Thumbnails</strong>.</p><h2 id="_1-system" tabindex="-1">1. System <a class="header-anchor" href="#_1-system" aria-label="Permalink to &quot;1. System&quot;">​</a></h2><ul><li><strong>Start Lertaro on System Boot</strong>: Automatically launches Lertaro upon Windows user login.</li><li><strong>Check for Updates on Startup</strong>: Automatically checks online for new releases whenever Lertaro starts.</li><li><strong>Silent In-Place Updates</strong>: Only available when &quot;Check for Updates&quot; is enabled. Downloads and installs updates silently in the background without pop-up interruptions.</li><li><strong>Enable Hardware Acceleration</strong>: Enabled by default. If your dual-GPU laptop (e.g. NVIDIA Advanced Optimus) fails to switch graphics cards because Lertaro is active, disable this to use software rendering. Requires restarting Lertaro.</li><li><strong>Hide System Tray Icon</strong>: Hides the icon from the Windows taskbar notification area. The logo inside the Quick Search bar continues to provide the full context menu, so access is never lost.</li><li><strong>Enable Everything Compatibility Service (IPC)</strong>: Emulates the standard Everything Win32 IPC protocol in the background. Third-party software (such as Directory Opus and Total Commander) can query Lertaro&#39;s in-memory index directly.</li><li><strong>Enable Fuzzy Matching</strong>: Enabled by default. When active, queries match non-contiguous character sequences. When disabled, queries require contiguous substring matches (see <a href="./../search-syntax.html"><strong>Search Syntax</strong></a>). Takes effect immediately.</li><li><strong>Query Token Delimiter</strong>: Single-character text box (default <code>:</code>). Defines the leading character for suffix tokens (e.g. <code>:.pdf</code>, <code>:@doc</code>, <code>:[S]</code>).</li><li><strong>Log Level</strong>: Dropdown selecting Error / Warning / Info (default) / Debug, controlling log verbosity across all processes.</li><li><strong>UI Language</strong>: Selects the active display language across the entire application.</li></ul><h2 id="_2-quick-search-window" tabindex="-1">2. Quick Search Window <a class="header-anchor" href="#_2-quick-search-window" aria-label="Permalink to &quot;2. Quick Search Window&quot;">​</a></h2><p>Fine-tunes the dimensions, layout, and priority rankings of the centered floating search bar:</p><h3 id="search-bar-layout" tabindex="-1">Search Bar Layout <a class="header-anchor" href="#search-bar-layout" aria-label="Permalink to &quot;Search Bar Layout&quot;">​</a></h3><ul><li><strong>Search Bar Width (Pixels)</strong>: Range <code>300–1200px</code>, default <code>570px</code>.</li><li><strong>Search Bar Height (Pixels)</strong>: Range <code>45–120px</code>, default <code>60px</code>. This value proportionally scales result icon sizes, line heights, and typography for visual balance.</li><li><strong>Show Clock in Search Box</strong>: Replaces the placeholder text with current date and time when the search box is empty. The clock disappears as soon as you type.</li><li><strong>Switch to Full Window on Second Hotkey Press</strong>: When enabled, pressing the global summon hotkey while the Quick Window is already open transitions directly into the Full Window, carrying over your active query.</li><li><strong>Lock Position</strong>: Prevents dragging the search bar to avoid accidental displacement.</li><li><strong>Automatically Fill Clipboard Text</strong>: Disabled by default. When the Quick Search Window opens without pre-filled text, new non-empty clipboard text is used as the search query. Manual paste and other windows are unaffected.</li><li><strong>Reset Layout Settings</strong>: Restores all search bar layout properties to initial defaults.</li></ul><h3 id="result-type-priority-trigger-characters" tabindex="-1">Result Type Priority &amp; Trigger Characters <a class="header-anchor" href="#result-type-priority-trigger-characters" aria-label="Permalink to &quot;Result Type Priority &amp; Trigger Characters&quot;">​</a></h3><ul><li><strong>Priority Sorting List</strong>: Drag or move items (Applications, System Settings, Files, Plugin Extensions) to adjust which types rank highest in search results.</li><li><strong>Exclusive Single-Character Trigger</strong>: Assign a dedicated character prefix (e.g. <code>;</code> for File Filters) to restrict searches exclusively to that type when typed at the start of a query.</li></ul><h2 id="_3-full-search-window" tabindex="-1">3. Full Search Window <a class="header-anchor" href="#_3-full-search-window" aria-label="Permalink to &quot;3. Full Search Window&quot;">​</a></h2><p>Configures default window geometry, columns, and sidebars for the main search window (<code>Ctrl+F</code>):</p><ul><li><strong>Window Width / Height (Pixels)</strong>: Width range <code>640–2000px</code> (default <code>854px</code>), height range <code>400–1400px</code> (default <code>480px</code>).</li><li><strong>Single Instance Only</strong>: When enabled, invoking the Full Window focuses the existing instance instead of spawning duplicate windows.</li><li><strong>Reset Search Window Settings</strong>: Reverts default dimensions to factory settings.</li><li><strong>Result Table Column Order</strong>: Customize the display order of columns (Name, Path, Date Modified, etc.) in the tabular view.</li><li><strong>Sidebar Filter Order</strong>: Reorder filter groups in the left sidebar; each category dynamically displays live matching item counts.</li><li><strong>Action Menu Group Order</strong>: Reorder action groups inside the context action menu (<code>Ctrl+O</code>).</li></ul><h2 id="_4-preview-window" tabindex="-1">4. Preview Window <a class="header-anchor" href="#_4-preview-window" aria-label="Permalink to &quot;4. Preview Window&quot;">​</a></h2><ul><li><strong>Preview Window Width / Height (Pixels)</strong>: Width range <code>250–900px</code>, height range <code>250–1200px</code>.</li><li><strong>Reset Preview Settings</strong>: Reverts the QuickLook preview window to standard default proportions, automatically constrained within visible screen bounds.</li></ul><h2 id="_5-quick-navigation" tabindex="-1">5. Quick Navigation <a class="header-anchor" href="#_5-quick-navigation" aria-label="Permalink to &quot;5. Quick Navigation&quot;">​</a></h2><ul><li><strong>Provider Order</strong>: Drag and reorder root categories in the Quick Navigation menu (Favorites, History, Open Folders, and third-party file manager bookmarks).</li></ul><h2 id="_6-previews-thumbnails" tabindex="-1">6. Previews &amp; Thumbnails <a class="header-anchor" href="#_6-previews-thumbnails" aria-label="Permalink to &quot;6. Previews &amp; Thumbnails&quot;">​</a></h2><ul><li><strong>File Preview Provider Order</strong>: Adjust the execution sequence and fallback order for preview renderers (built-in media decoders vs. third-party QuickLook bridge).</li><li><strong>Thumbnail Provider Order</strong>: Adjust the resolution priority for file icon and thumbnail extraction providers.</li></ul>',19)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
